42	// EntireSettings represents the .entire/settings.json configuration
43	type EntireSettings struct {
44		// Enabled indicates whether Entire is active. When false, CLI commands
45		// show a disabled message and hooks exit silently. Defaults to true.
46		Enabled bool `json:"enabled"`
47	
48		// LocalDev indicates whether to use "go run" instead of the "entire" binary
49		// This is used for development when the binary is not installed
50		LocalDev bool `json:"local_dev,omitempty"`
51	
52		// LogLevel sets the logging verbosity (debug, info, warn, error).
53		// Can be overridden by ENTIRE_LOG_LEVEL environment variable.
