110	// SummaryGenerationSettings configures provider selection for on-demand
111	// checkpoint summaries generated by explain --generate.
112	type SummaryGenerationSettings struct {
113		// Provider is the selected summary provider agent name
114		// (for example "claude-code", "codex", or "gemini").
115		Provider string `json:"provider,omitempty"`
