121	// Validate returns an error if the settings combination is semantically invalid.
122	// A model without a provider is meaningless: the model hint needs a provider to
123	// route to. The load path calls Validate() after merging, catching hand-edited
124	// files that land in this state.
125	func (s *SummaryGenerationSettings) Validate() error {
126		if s == nil {
127			return nil
128		}
129		if s.Model != "" && s.Provider == "" {
130			return fmt.Errorf("summary_generation.model %q set without summary_generation.provider", s.Model)
131		}
132		return nil
133	}
134	
135	// SetProvider updates the provider and optionally the model, clearing any stale
136	// model from the previous provider when switching without a replacement.
137	// An empty newProvider preserves the current provider; an empty newModel
138	// preserves the current model unless the provider is changing, in which case
139	// the old model is cleared to avoid passing (say) a Claude model to Codex.
140	func (s *SummaryGenerationSettings) SetProvider(newProvider, newModel string) {
141		if s == nil {
142			return
143		}
144		if newProvider != "" && s.Provider != "" && s.Provider != newProvider && newModel == "" {
145			s.Model = ""
146		}
147		if newProvider != "" {
148			s.Provider = newProvider
149		}
150		if newModel != "" {
151			s.Model = newModel
152		}
153	}
154	
155	// RedactionSettings configures redaction behavior beyond the default secret detection.
156	type RedactionSettings struct {
157		PII *PIISettings `json:"pii,omitempty"`
158	}
159	
160	// PIISettings configures PII detection categories.
161	// When Enabled is true, email and phone default to true; address defaults to false.
162	type PIISettings struct {
163		Enabled        bool              `json:"enabled"`
164		Email          *bool             `json:"email,omitempty"`
165		Phone          *bool             `json:"phone,omitempty"`
166		Address        *bool             `json:"address,omitempty"`
