168	}
169	
170	// GetCommitLinking returns the effective commit linking mode.
171	// Returns the explicit value if set, otherwise defaults to "prompt"
172	// to preserve existing user behavior.
173	func (s *EntireSettings) GetCommitLinking() string {
174		if s.CommitLinking != "" {
175			return s.CommitLinking
176		}
177		return CommitLinkingPrompt
178	}
179	
180	// SummaryTimeoutValue returns the configured hard deadline for
181	// `entire explain --generate` summary generation. Zero means "unset" --
182	// the caller picks the default. Negative values are treated as unset.
183	func (s *EntireSettings) SummaryTimeoutValue() time.Duration {
184		if s.SummaryTimeoutSeconds < 1 {
185			return 0
