190	// ReviewConfig holds the per-agent review configuration. Both fields are
191	// optional; together they describe what `entire review` should ask the
192	// agent to do.
193	//
194	// Precedence when composing the review prompt sent to the agent:
195	//   - If Prompt is non-empty, it is used verbatim.
196	//   - Otherwise, Skills are composed into a default template
197	//     ("Please run these review skills in order: 1. /X 2. /Y").
198	//
199	// Skills are always recorded on the checkpoint metadata regardless of
200	// which path composed the prompt — they're the structured, queryable
201	// tag alongside ReviewPrompt (which is the ground truth).
202	type ReviewConfig struct {
203		// Skills is the list of slash-prefixed skill invocations configured
204		// for this agent. May be empty when Prompt carries the full request.
205		Skills []string `json:"skills,omitempty"`
206	
207		// Prompt, when non-empty, is used verbatim as the review prompt
208		// instead of the skills-composed template. Lets users include
209		// context (e.g. "focus on security issues, then run /X").
210		Prompt string `json:"prompt,omitempty"`
211	}
212	
213	// IsZero reports whether the config is effectively unset.
214	func (c ReviewConfig) IsZero() bool {
215		return len(c.Skills) == 0 && c.Prompt == ""
216	}
217	
218	// ReviewConfigFor returns the configured review config for the given agent.
219	// Returns a zero-value config when the agent has no entry; callers should
220	// check IsZero (or the individual fields) to decide whether configuration
221	// is present.
222	func (s *EntireSettings) ReviewConfigFor(agentName string) ReviewConfig {
223		if s == nil {
224			return ReviewConfig{}
