228	
229	// Load loads the Entire settings from .entire/settings.json,
230	// then applies any overrides from .entire/settings.local.json if it exists.
231	// Returns default settings if neither file exists.
232	// Works correctly from any subdirectory within the repository.
233	func Load(ctx context.Context) (*EntireSettings, error) {
234		// Get absolute paths for settings files
235		settingsFileAbs, err := paths.AbsPath(ctx, EntireSettingsFile)
236		if err != nil {
237			settingsFileAbs = EntireSettingsFile // Fallback to relative
238		}
239		localSettingsFileAbs, err := paths.AbsPath(ctx, EntireSettingsLocalFile)
240		if err != nil {
241			localSettingsFileAbs = EntireSettingsLocalFile // Fallback to relative
242		}
243	
244		return loadMergedSettings(settingsFileAbs, localSettingsFileAbs)
245	}
246	
247	func loadMergedSettings(settingsFileAbs, localSettingsFileAbs string) (*EntireSettings, error) {
248		// Load base settings
249		settings, err := loadFromFile(settingsFileAbs)
250		if err != nil {
251			return nil, fmt.Errorf("reading settings file: %w", err)
252		}
253	
254		// Apply local overrides if they exist
255		localData, err := os.ReadFile(localSettingsFileAbs) //nolint:gosec // path is from AbsPath or constant
256		if err != nil {
257			if !os.IsNotExist(err) {
258				return nil, fmt.Errorf("reading local settings file: %w", err)
259			}
260			// Local file doesn't exist, continue without overrides
261		} else {
262			if err := mergeJSON(settings, localData); err != nil {
263				return nil, fmt.Errorf("merging local settings: %w", err)
264			}
265		}
266	
267		// Re-validate after merge. Individual files are validated by loadFromFile,
268		// but mergeJSON patches fields independently and can produce combinations
269		// (e.g. model without provider when the local override sets only a model
270		// on top of a base with no provider) that neither file alone contained.
271		if err := settings.SummaryGeneration.Validate(); err != nil {
272			return nil, fmt.Errorf("merged settings invalid: %w", err)
273		}
274	
275		return settings, nil
276	}
277	
278	// LoadFromFile loads settings from a specific file path without merging local overrides.
279	// Returns default settings if the file doesn't exist.
280	// Use this when you need to display individual settings files separately.
281	func LoadFromFile(filePath string) (*EntireSettings, error) {
282		return loadFromFile(filePath)
283	}
284	
285	// LoadFromBytes parses settings from raw JSON bytes without merging local overrides.
286	// Use this when you have settings content from a non-file source (e.g., git show).
287	func LoadFromBytes(data []byte) (*EntireSettings, error) {
288		s := &EntireSettings{Enabled: true}
289		dec := json.NewDecoder(bytes.NewReader(data))
290		dec.DisallowUnknownFields()
291		if err := dec.Decode(s); err != nil {
292			return nil, fmt.Errorf("parsing settings: %w", err)
293		}
294		return s, nil
295	}
296	
297	// loadFromFile loads settings from a specific file path.
298	// Returns default settings if the file doesn't exist.
299	func loadFromFile(filePath string) (*EntireSettings, error) {
300		settings := &EntireSettings{
301			Enabled: true, // Default to enabled
302		}
303	
304		data, err := os.ReadFile(filePath) //nolint:gosec // path is from caller
305		if err != nil {
306			if os.IsNotExist(err) {
307				return settings, nil
308			}
309			return nil, fmt.Errorf("%w", err)
310		}
311	
312		dec := json.NewDecoder(bytes.NewReader(data))
313		dec.DisallowUnknownFields()
314		if err := dec.Decode(settings); err != nil {
315			return nil, fmt.Errorf("parsing settings file: %w", err)
316		}
317	
318		// Validate commit_linking if set
319		if settings.CommitLinking != "" && settings.CommitLinking != CommitLinkingAlways && settings.CommitLinking != CommitLinkingPrompt {
320			return nil, fmt.Errorf("invalid commit_linking value %q: must be %q or %q", settings.CommitLinking, CommitLinkingAlways, CommitLinkingPrompt)
321		}
322	
323		// SummaryGeneration is NOT validated here — individual files may
324		// legitimately contain only a model (provider comes from another file).
325		// Validation happens after merge in Load().
326	
327		return settings, nil
328	}
329	
330	// mergeJSON merges JSON data into existing settings.
331	// Only non-zero values from the JSON override existing settings.
332	func mergeJSON(settings *EntireSettings, data []byte) error {
333		// Validate that there are no unknown keys using strict decoding.
334		dec := json.NewDecoder(bytes.NewReader(data))
335		dec.DisallowUnknownFields()
336		var temp EntireSettings
337		if err := dec.Decode(&temp); err != nil {
338			return fmt.Errorf("parsing JSON: %w", err)
339		}
340	
341		// Parse into a map to check which fields are present.
342		var raw map[string]json.RawMessage
343		if err := json.Unmarshal(data, &raw); err != nil {
344			return fmt.Errorf("parsing JSON: %w", err)
345		}
346	
347		if err := mergeScalarFields(settings, raw); err != nil {
348			return err
349		}
350		if err := mergeStrategyOptions(settings, raw); err != nil {
351			return err
352		}
353		if err := mergeSummaryGeneration(settings, raw); err != nil {
354			return err
355		}
356		if err := mergeCommitLinking(settings, raw); err != nil {
357			return err
358		}
359	
360		// Merge redaction sub-fields if present (field-level, not wholesale replace).
361		if redactionRaw, ok := raw["redaction"]; ok {
362			if settings.Redaction == nil {
363				settings.Redaction = &RedactionSettings{}
364			}
365			if err := mergeRedaction(settings.Redaction, redactionRaw); err != nil {
366				return fmt.Errorf("parsing redaction field: %w", err)
367			}
368		}
369	
370		return nil
371	}
372	
373	// mergeScalarFields merges simple bool, *bool, string, and int fields from raw JSON.
374	func mergeScalarFields(settings *EntireSettings, raw map[string]json.RawMessage) error {
375		if err := mergeRawBool(raw, "enabled", &settings.Enabled); err != nil {
376			return err
377		}
378		if err := mergeRawBool(raw, "local_dev", &settings.LocalDev); err != nil {
379			return err
380		}
381		if err := mergeRawBool(raw, "absolute_git_hook_path", &settings.AbsoluteGitHookPath); err != nil {
382			return err
383		}
384		if err := mergeRawBool(raw, "external_agents", &settings.ExternalAgents); err != nil {
385			return err
386		}
387		if err := mergeRawBool(raw, "vercel", &settings.Vercel); err != nil {
388			return err
389		}
390		if err := mergeRawBoolPtr(raw, "telemetry", &settings.Telemetry); err != nil {
391			return err
392		}
393		if err := mergeRawBoolPtr(raw, "sign_checkpoint_commits", &settings.SignCheckpointCommits); err != nil {
394			return err
395		}
396		if err := mergeRawStringNonEmpty(raw, "log_level", &settings.LogLevel); err != nil {
397			return err
398		}
399		if err := mergeRawInt(raw, "summary_timeout_seconds", &settings.SummaryTimeoutSeconds); err != nil {
400			return err
401		}
402		return nil
403	}
404	
405	func mergeRawBool(raw map[string]json.RawMessage, key string, dst *bool) error {
406		v, ok := raw[key]
407		if !ok {
408			return nil
409		}
410		return unmarshalField(key, v, dst)
411	}
412	
413	func mergeRawBoolPtr(raw map[string]json.RawMessage, key string, dst **bool) error {
414		v, ok := raw[key]
415		if !ok {
416			return nil
417		}
418		var b bool
419		if err := unmarshalField(key, v, &b); err != nil {
420			return err
421		}
422		*dst = &b
423		return nil
424	}
425	
426	func mergeRawStringNonEmpty(raw map[string]json.RawMessage, key string, dst *string) error {
427		v, ok := raw[key]
428		if !ok {
429			return nil
430		}
431		var s string
432		if err := unmarshalField(key, v, &s); err != nil {
433			return err
434		}
435		if s != "" {
436			*dst = s
437		}
438		return nil
439	}
440	
441	func mergeRawInt(raw map[string]json.RawMessage, key string, dst *int) error {
442		v, ok := raw[key]
443		if !ok {
444			return nil
445		}
446		return unmarshalField(key, v, dst)
447	}
448	
449	func unmarshalField(key string, data json.RawMessage, dst any) error {
450		if err := json.Unmarshal(data, dst); err != nil {
451			return fmt.Errorf("parsing %s field: %w", key, err)
452		}
453		return nil
454	}
455	
456	func mergeStrategyOptions(settings *EntireSettings, raw map[string]json.RawMessage) error {
457		optionsRaw, ok := raw["strategy_options"]
458		if !ok {
459			return nil
460		}
461		var opts map[string]any
462		if err := unmarshalField("strategy_options", optionsRaw, &opts); err != nil {
463			return err
464		}
465		if settings.StrategyOptions == nil {
466			settings.StrategyOptions = opts
467		} else {
468			for k, v := range opts {
469				settings.StrategyOptions[k] = v
470			}
471		}
472		return nil
473	}
474	
475	func mergeSummaryGeneration(settings *EntireSettings, raw map[string]json.RawMessage) error {
476		summaryRaw, ok := raw["summary_generation"]
477		if !ok {
478			return nil
479		}
480		if settings.SummaryGeneration == nil {
481			settings.SummaryGeneration = &SummaryGenerationSettings{}
482		}
483	
484		var summaryFields map[string]json.RawMessage
485		if err := unmarshalField("summary_generation", summaryRaw, &summaryFields); err != nil {
486			return err
487		}
488	
489		_, modelInOverride := summaryFields["model"]
490	
491		if providerRaw, ok := summaryFields["provider"]; ok {
492			var provider string
493			if err := unmarshalField("summary_generation.provider", providerRaw, &provider); err != nil {
494				return err
495			}
496			// If the override switches providers without also setting a model,
497			// the base's model was tuned to the old provider and would likely
498			// cause a runtime failure when handed to the new one (e.g. codex
499			// rejecting "sonnet"). Clear it so the new provider falls back to
500			// its own default.
501			if provider != settings.SummaryGeneration.Provider && !modelInOverride {
502				settings.SummaryGeneration.Model = ""
503			}
504			settings.SummaryGeneration.Provider = provider
505		}
506	
507		if modelRaw, ok := summaryFields["model"]; ok {
508			var model string
509			if err := unmarshalField("summary_generation.model", modelRaw, &model); err != nil {
510				return err
511			}
512			settings.SummaryGeneration.Model = model
513		}
514		return nil
515	}
516	
517	func mergeCommitLinking(settings *EntireSettings, raw map[string]json.RawMessage) error {
518		commitLinkingRaw, ok := raw["commit_linking"]
519		if !ok {
520			return nil
521		}
522		var cl string
523		if err := unmarshalField("commit_linking", commitLinkingRaw, &cl); err != nil {
524			return err
525		}
526		if cl == "" {
527			return nil
528		}
529		switch cl {
530		case CommitLinkingAlways, CommitLinkingPrompt:
531			settings.CommitLinking = cl
532		default:
533			return fmt.Errorf("invalid commit_linking value %q: must be %q or %q", cl, CommitLinkingAlways, CommitLinkingPrompt)
534		}
535		return nil
536	}
537	
538	// mergeRedaction merges redaction overrides into existing RedactionSettings.
539	// Only fields present in the override JSON are applied.
540	func mergeRedaction(dst *RedactionSettings, data json.RawMessage) error {
541		var raw map[string]json.RawMessage
542		if err := json.Unmarshal(data, &raw); err != nil {
543			return fmt.Errorf("parsing redaction: %w", err)
544		}
545		if piiRaw, ok := raw["pii"]; ok {
546			if dst.PII == nil {
547				dst.PII = &PIISettings{}
548			}
549			if err := mergePIISettings(dst.PII, piiRaw); err != nil {
550				return err
551			}
552		}
553		return nil
554	}
555	
556	// mergePIISettings merges PII overrides into existing PIISettings.
557	// Only fields present in the override JSON are applied; missing fields
558	// are preserved from the base settings.
559	func mergePIISettings(dst *PIISettings, data json.RawMessage) error {
560		var raw map[string]json.RawMessage
561		if err := json.Unmarshal(data, &raw); err != nil {
562			return fmt.Errorf("parsing pii: %w", err)
563		}
564		if v, ok := raw["enabled"]; ok {
565			if err := json.Unmarshal(v, &dst.Enabled); err != nil {
566				return fmt.Errorf("parsing pii.enabled: %w", err)
567			}
568		}
569		if v, ok := raw["email"]; ok {
570			var b bool
571			if err := json.Unmarshal(v, &b); err != nil {
572				return fmt.Errorf("parsing pii.email: %w", err)
573			}
574			dst.Email = &b
575		}
576		if v, ok := raw["phone"]; ok {
577			var b bool
578			if err := json.Unmarshal(v, &b); err != nil {
579				return fmt.Errorf("parsing pii.phone: %w", err)
580			}
581			dst.Phone = &b
582		}
583		if v, ok := raw["address"]; ok {
584			var b bool
585			if err := json.Unmarshal(v, &b); err != nil {
586				return fmt.Errorf("parsing pii.address: %w", err)
587			}
588			dst.Address = &b
589		}
590		if v, ok := raw["custom_patterns"]; ok {
591			var cp map[string]string
592			if err := json.Unmarshal(v, &cp); err != nil {
593				return fmt.Errorf("parsing pii.custom_patterns: %w", err)
594			}
595			if dst.CustomPatterns == nil {
596				dst.CustomPatterns = cp
597			} else {
598				for k, val := range cp {
599					dst.CustomPatterns[k] = val
600				}
601			}
602		}
603		return nil
604	}
