606	// IsSetUp returns true if Entire has been set up in the current repository.
607	// This checks if .entire/settings.json exists.
608	// Use this to avoid creating files/directories in repos where Entire was never enabled.
609	func IsSetUp(ctx context.Context) bool {
610		settingsFileAbs, err := paths.AbsPath(ctx, EntireSettingsFile)
611		if err != nil {
612			return false
613		}
614		_, err = os.Stat(settingsFileAbs)
