728	// CheckpointRemoteConfig holds the structured checkpoint remote configuration.
729	// Stored in strategy_options.checkpoint_remote as {"provider": "github", "repo": "org/repo"}.
730	type CheckpointRemoteConfig struct {
731		Provider string // e.g., "github"
732		Repo     string // e.g., "org/checkpoints-repo"
733	}
734	
735	// Owner returns the owner portion of the repo field (before the slash).
736	// Returns empty string if the repo field doesn't contain a slash.
737	func (c *CheckpointRemoteConfig) Owner() string {
738		parts := strings.SplitN(c.Repo, "/", 2)
739		if len(parts) < 2 {
740			return ""
741		}
742		return parts[0]
743	}
