771	// IsCheckpointsV2Enabled checks if checkpoints v2 is enabled.
772	// Returns true when either checkpoints_v2 is set or checkpoints_version is 2.
773	func (s *EntireSettings) IsCheckpointsV2Enabled() bool {
774		if s.CheckpointsVersion() == 2 {
775			return true
776		}
777		if s.StrategyOptions == nil {
778			return false
779		}
780		val, ok := s.StrategyOptions["checkpoints_v2"].(bool)
781		return ok && val
782	}
