784	// CheckpointsVersion returns the configured checkpoints format version from
785	// strategy_options.checkpoints_version. Returns 1 when unset, invalid, or
786	// unsupported. The currently supported versions are 1 and 2.
787	func (s *EntireSettings) CheckpointsVersion() int {
788		if s.StrategyOptions == nil {
789			return 1
790		}
791		val, ok := s.StrategyOptions["checkpoints_version"]
792		if !ok {
793			return 1
794		}
795		version, ok := parseCheckpointsVersion(val)
796		if ok {
797			return version
798		}
799		return 1
800	}
801	
802	func parseCheckpointsVersion(val any) (int, bool) {
803		v, ok := val.(int)
804		if ok && (v == 1 || v == 2) {
805			return v, true
806		}
807		floatV, ok := val.(float64)
808		if ok && (floatV == 1 || floatV == 2) {
809			return int(floatV), true
810		}
811		stringV, ok := val.(string)
812		if ok {
813			parsed, err := strconv.Atoi(stringV)
814			if err == nil && (parsed == 1 || parsed == 2) {
815				return parsed, true
816			}
817		}
818		return 1, false
819	}
820	
821	// IsPushV2RefsEnabled checks if pushing v2 refs is enabled.
822	// checkpoints_version: 2 forces v2 ref pushes on, regardless of push_v2_refs.
823	func (s *EntireSettings) IsPushV2RefsEnabled() bool {
824		if s.CheckpointsVersion() == 2 {
825			return true
826		}
827		if !s.IsCheckpointsV2Enabled() {
828			return false
829		}
830		if s.StrategyOptions == nil {
831			return false
832		}
833		val, ok := s.StrategyOptions["push_v2_refs"].(bool)
834		return ok && val
835	}
836	
837	// GetFullTranscriptGenerationRetentionDays returns the retention window for
838	// archived checkpoints v2 /full/* generations. Invalid, missing, or
839	// non-positive values fall back to the documented default.
840	func (s *EntireSettings) GetFullTranscriptGenerationRetentionDays() int {
841		if s.StrategyOptions == nil {
842			return defaultGenerationRetentionDays
843		}
844	
845		val, ok := s.StrategyOptions["full_transcript_generation_retention_days"]
846		if !ok {
847			return defaultGenerationRetentionDays
848		}
849	
850		switch days := val.(type) {
851		case int:
852			if days > 0 {
853				return days
854			}
855		case float64:
856			intDays := int(days)
857			if intDays > 0 && days == float64(intDays) {
858				return intDays
859			}
860		}
861	
862		return defaultGenerationRetentionDays
863	}
864	
865	// IsFilteredFetchesEnabled checks if fetches should use --filter=blob:none.
866	// When enabled, filtered fetches always use resolved URLs rather than remote
867	// names to avoid persisting promisor settings onto named remotes.
868	func (s *EntireSettings) IsFilteredFetchesEnabled() bool {
869		if s.StrategyOptions == nil {
870			return false
871		}
872		val, ok := s.StrategyOptions["filtered_fetches"].(bool)
873		return ok && val
874	}
875	
876	// IsPushSessionsDisabled checks if push_sessions is disabled in settings.
877	// Returns true if push_sessions is explicitly set to false.
878	func (s *EntireSettings) IsPushSessionsDisabled() bool {
879		if s.StrategyOptions == nil {
880			return false
881		}
882		val, exists := s.StrategyOptions["push_sessions"]
883		if !exists {
884			return false
885		}
886		if boolVal, ok := val.(bool); ok {
887			return !boolVal // disabled = !push_sessions
888		}
889		return false
890	}
891	
892	// IsExternalAgentsEnabled checks if external agent discovery is enabled in settings.
893	// Returns false by default if settings cannot be loaded or the key is missing.
894	func IsExternalAgentsEnabled(ctx context.Context) bool {
895		s, err := Load(ctx)
896		if err != nil {
897			return false
898		}
899		return s.ExternalAgents
900	}
901	
902	// IsSignCheckpointCommitsEnabled returns true if checkpoint commits should be signed.
903	// Defaults to true when the setting is not explicitly set.
904	func (s *EntireSettings) IsSignCheckpointCommitsEnabled() bool {
905		return s.SignCheckpointCommits == nil || *s.SignCheckpointCommits
906	}
907	
908	// IsSignCheckpointCommitsEnabled checks if checkpoint commit signing is enabled in settings.
909	// Returns true by default if settings cannot be loaded or the key is missing.
910	func IsSignCheckpointCommitsEnabled(ctx context.Context) bool {
911		s, err := Load(ctx)
912		if err != nil {
913			return true
914		}
915		return s.IsSignCheckpointCommitsEnabled()
916	}
917	
918	// Save saves the settings to .entire/settings.json.
919	func Save(ctx context.Context, settings *EntireSettings) error {
920		return saveToFile(ctx, settings, EntireSettingsFile)
921	}
922	
923	// SaveLocal saves the settings to .entire/settings.local.json.
924	func SaveLocal(ctx context.Context, settings *EntireSettings) error {
925		return saveToFile(ctx, settings, EntireSettingsLocalFile)
926	}
927	
928	// saveToFile saves settings to the specified file path.
929	func saveToFile(ctx context.Context, settings *EntireSettings, filePath string) error {
930		// Get absolute path for the file
931		filePathAbs, err := paths.AbsPath(ctx, filePath)
932		if err != nil {
933			filePathAbs = filePath // Fallback to relative
934		}
935	
936		// Ensure directory exists
937		dir := filepath.Dir(filePathAbs)
938		if err := os.MkdirAll(dir, 0o750); err != nil {
939			return fmt.Errorf("creating settings directory: %w", err)
940		}
941	
942		data, err := jsonutil.MarshalIndentWithNewline(settings, "", "  ")
943		if err != nil {
944			return fmt.Errorf("marshaling settings: %w", err)
945		}
946	
947		//nolint:gosec // G306: settings file is config, not secrets; 0o644 is appropriate
948		if err := os.WriteFile(filePathAbs, data, 0o644); err != nil {
949			return fmt.Errorf("writing settings file: %w", err)
950		}
951		return nil
952	}
