55	func newAttachCmd() *cobra.Command {
56		var (
57			force      bool
58			agentFlag  string
59			reviewFlag bool
60			skillsFlag []string
61		)
62		cmd := &cobra.Command{
63			Use:   "attach <session-id>",
64			Short: "Attach an existing agent session",
65			Long: `Attach an existing agent session that wasn't captured by hooks.
66	
67	This creates a checkpoint from the session's transcript and links it to the
68	last commit. Use this when hooks failed to fire or weren't installed when
69	the session started, or to attach a research session.
70	
71	If the last commit already has a checkpoint, the session is added to it.
72	Otherwise a new checkpoint is created.
73	
74	Use --review to tag the attached session as an agent review. The
75	first user prompt in the transcript is recorded as the review prompt.
76	Pass --skills to declare which skills were actually run; omit to
77	attach a review without a declared skills list.
78	
79	Works with any registered agent, including external agents enabled via
80	external_agents in settings. Run 'entire configure' to see the full list.`,
81			RunE: func(cmd *cobra.Command, args []string) error {
82				if len(args) != 1 {
83					return cmd.Help()
84				}
85				if checkDisabledGuard(cmd.Context(), cmd.OutOrStdout()) {
86					return nil
87				}
88				// Discover external agents so --agent <external-name> is recognized
89				// and so auto-detection can find transcripts from external agents.
90				external.DiscoverAndRegister(cmd.Context())
91				agentName := types.AgentName(agentFlag)
92				opts := attachOptions{
93					Force:                force,
94					Review:               reviewFlag,
95					ReviewSkillsOverride: skillsFlag,
96				}
97				return runAttachSurfaceReviewErrors(cmd, args[0], agentName, opts)
98			},
99		}
100		cmd.Flags().BoolVarP(&force, "force", "f", false, "Skip confirmation and amend the last commit with the checkpoint trailer")
101		cmd.Flags().StringVarP(&agentFlag, "agent", "a", string(agent.DefaultAgentName), "Agent that created the session (see 'entire configure' for registered agents, including external)")
102		cmd.Flags().BoolVar(&reviewFlag, "review", false, "Tag the attached session as an agent review")
103		cmd.Flags().StringSliceVar(&skillsFlag, "skills", nil, "Optional: declare which review skills were run in this session. Only used with --review")
104		return cmd
105	}
106	
107	// resolveReviewSkills returns the skills list to record on an
108	// attach-as-review. Only the user's --skills flag counts: configured
109	// settings.Review[agent] is the spawn-path default ("what I'd run if I
110	// used 'entire review'"), not a claim about what actually happened in a
111	// given manual session. Silently attaching configured skills would
112	// misrepresent the session as having run skills it may not have.
113	//
114	// Empty is a valid result — the attach still tags the session as a
115	// review via Kind + ReviewPrompt (the session's first user prompt). The
116	// skills list is a queryable convenience, not the source of truth.
117	func resolveReviewSkills(flagSkills []string) []string {
118		if len(flagSkills) == 0 {
119			return nil
120		}
121		return flagSkills
122	}
123	
124	// runAttachSurfaceReviewErrors wraps runAttach so review-mode errors reach
125	// the user as clear stderr messages rather than generic cobra error output.
126	// The non-review path preserves the existing runAttach return-err behavior.
127	func runAttachSurfaceReviewErrors(cmd *cobra.Command, sessionID string, agentName types.AgentName, opts attachOptions) error {
128		err := runAttach(cmd.Context(), cmd.OutOrStdout(), sessionID, agentName, opts)
129		if err != nil && opts.Review {
130			cmd.SilenceUsage = true
131			fmt.Fprintln(cmd.ErrOrStderr(), err.Error())
132			return NewSilentError(err)
133		}
134		return err
135	}
