302	// writeAttachCheckpointV2 writes attach-created checkpoints into the v2 refs.
303	func writeAttachCheckpointV2(ctx context.Context, repo *git.Repository, opts cpkg.WriteCommittedOptions) error {
304		v2URL, err := remote.FetchURL(ctx)
305		if err != nil {
306			logging.Debug(ctx, "attach: using origin for v2 store fetch remote",
307				slog.String("error", err.Error()),
308			)
309		}
310		v2Store := cpkg.NewV2GitStore(repo, v2URL)
311		if err := v2Store.WriteCommitted(ctx, opts); err != nil {
312			return fmt.Errorf("v2 write committed: %w", err)
313		}
314		return nil
315	}
316	
317	// getHeadCommit returns the HEAD commit object.
318	func getHeadCommit(repo *git.Repository) (*object.Commit, error) {
319		headRef, err := repo.Head()
320		if err != nil {
321			return nil, fmt.Errorf("failed to get HEAD: %w", err)
322		}
323		commit, err := repo.CommitObject(headRef.Hash())
324		if err != nil {
325			return nil, fmt.Errorf("failed to get HEAD commit: %w", err)
326		}
327		return commit, nil
328	}
329	
330	// resolveCheckpointID returns the checkpoint ID to use for the attach.
331	// If HEAD already has an Entire-Checkpoint trailer, reuses that ID (the session
332	// gets added as an additional session in the existing checkpoint).
333	// Otherwise generates a new ID.
334	func resolveCheckpointID(headCommit *object.Commit) (id.CheckpointID, bool) {
335		existing := trailers.ParseAllCheckpoints(headCommit.Message)
336		if len(existing) > 0 {
337			return existing[len(existing)-1], true
338		}
339	
340		cpID, err := id.Generate()
341		if err != nil {
342			// Generation only fails if crypto/rand fails — extremely unlikely.
343			// Fall back to empty which will cause WriteCommitted to fail with a clear error.
344			return id.EmptyCheckpointID, false
345		}
346		return cpID, false
347	}
348	
349	// saveAttachSessionState creates or updates the session state file for the attached session.
350	// If existingState is non-nil, it is updated in place (avoids a redundant disk load).
351	// reviewSkills is the resolved skills list when opts.Review is true; ignored otherwise.
352	func saveAttachSessionState(ctx context.Context, existingState *session.State, sessionID string, agentType types.AgentType, transcriptPath string, checkpointID id.CheckpointID, meta transcriptMetadata, tokenUsage *agent.TokenUsage, opts attachOptions, reviewSkills []string) error {
353		stateStore, err := session.NewStateStore(ctx)
354		if err != nil {
355			return fmt.Errorf("failed to open session store: %w", err)
356		}
357	
358		now := time.Now()
359		state := existingState
360		if state == nil {
361			state = &session.State{
362				SessionID: sessionID,
363				StartedAt: now,
364			}
365		}
366	
367		state.CLIVersion = versioninfo.Version
368		state.AttachedManually = true
369		state.AgentType = agentType
370		state.TranscriptPath = transcriptPath
371		state.LastCheckpointID = checkpointID
372		state.Phase = session.PhaseEnded
373		state.LastInteractionTime = &now
374		if meta.TurnCount > 0 {
375			state.SessionTurnCount = meta.TurnCount
376		}
377		if meta.Model != "" {
378			state.ModelName = meta.Model
379		}
380		if meta.FirstPrompt != "" {
381			state.LastPrompt = meta.FirstPrompt
382		}
383		if tokenUsage != nil {
384			state.TokenUsage = tokenUsage
385		}
386		if opts.Review {
387			state.Kind = session.KindAgentReview
388			state.ReviewSkills = reviewSkills
389			state.ReviewPrompt = meta.FirstPrompt
390		}
391	
392		if err := stateStore.Save(ctx, state); err != nil {
393			return fmt.Errorf("failed to save session state: %w", err)
394		}
395		return nil
396	}
397	
398	// validateAttachPreconditions checks session ID format and git repo state.
399	// Returns the existing session state if the session is already tracked (nil if new).
400	func validateAttachPreconditions(ctx context.Context, repo *git.Repository, sessionID string) (*session.State, error) {
401		if err := validation.ValidateSessionID(sessionID); err != nil {
402			return nil, fmt.Errorf("invalid session ID: %w", err)
403		}
404	
405		if strategy.IsEmptyRepository(repo) {
406			return nil, errors.New("repository has no commits yet — make an initial commit before running attach")
407		}
408	
409		store, err := session.NewStateStore(ctx)
410		if err != nil {
411			return nil, fmt.Errorf("failed to open session store: %w", err)
412		}
413		existing, err := store.Load(ctx, sessionID)
414		if err != nil {
415			return nil, fmt.Errorf("failed to check existing session: %w", err)
416		}
417	
418		return existing, nil
419	}
420	
421	// resolveAgentAndTranscript resolves the agent and transcript path.
422	// For existing sessions, resolves the agent from session state's AgentType.
423	// For new sessions, uses the --agent flag with auto-detection fallback.
424	func resolveAgentAndTranscript(ctx context.Context, w io.Writer, sessionID string, agentName types.AgentName, existingState *session.State) (agent.Agent, string, error) {
425		ag, err := resolveAgent(existingState, agentName)
426		if err != nil {
427			return nil, "", err
428		}
429	
430		transcriptPath, err := resolveAndValidateTranscript(ctx, sessionID, ag)
431		if err != nil {
432			// Auto-detect: try all other agents.
433			detectedAg, detectedPath, detectErr := detectAgentByTranscript(ctx, sessionID, agentName)
434			if detectErr != nil {
435				return nil, "", fmt.Errorf("%w (also tried auto-detecting other agents: %w)", err, detectErr)
436			}
437			ag = detectedAg
438			transcriptPath = detectedPath
439			logging.Info(ctx, "auto-detected agent from transcript", "agent", ag.Name())
440			fmt.Fprintf(w, "Auto-detected agent: %s\n", ag.Name())
441		}
442	
443		return ag, transcriptPath, nil
444	}
445	
446	// resolveAgent resolves the agent to use. For existing sessions with an AgentType,
447	// uses agent.GetByAgentType. Otherwise falls back to the --agent flag.
448	func resolveAgent(existingState *session.State, agentName types.AgentName) (agent.Agent, error) {
449		if existingState != nil && existingState.AgentType != "" {
450			ag, err := agent.GetByAgentType(existingState.AgentType)
451			if err == nil {
452				return ag, nil
453			}
454			// Fall through to flag-based resolution.
455		}
456		ag, err := agent.Get(agentName)
457		if err != nil {
458			return nil, fmt.Errorf("agent %q not available: %w", agentName, err)
459		}
460		return ag, nil
461	}
462	
463	// resolveAndValidateTranscript finds the transcript file for a session, searching alternative
464	// project directories if needed.
465	func resolveAndValidateTranscript(ctx context.Context, sessionID string, ag agent.Agent) (string, error) {
466		transcriptPath, err := resolveTranscriptPath(ctx, sessionID, ag)
467		if err != nil {
468			return "", fmt.Errorf("failed to resolve transcript path: %w", err)
469		}
470		// Only call PrepareTranscript when the file already exists — it flushes
471		// in-progress writes, but can't conjure a file that was never started.
472		// This avoids agents like Cursor polling for 3s on non-existent files
473		// during auto-detection.
474		if _, statErr := os.Stat(transcriptPath); statErr == nil {
475			if preparer, ok := agent.AsTranscriptPreparer(ag); ok {
476				if prepErr := preparer.PrepareTranscript(ctx, transcriptPath); prepErr != nil {
477					logging.Debug(ctx, "PrepareTranscript failed (best-effort)", "error", prepErr)
478				}
479			}
480			return transcriptPath, nil
481		}
482		found, searchErr := searchTranscriptInProjectDirs(sessionID, ag)
483		if searchErr == nil {
484			logging.Info(ctx, "found transcript in alternative project directory", "path", found)
485			return found, nil
486		}
487		logging.Debug(ctx, "fallback transcript search failed", "error", searchErr)
488		return "", fmt.Errorf("transcript not found for agent %q with session %s; is the session ID correct?", ag.Name(), sessionID)
489	}
490	
491	// detectAgentByTranscript tries all registered agents (except skip) to find one whose
492	// transcript resolution succeeds for the given session ID.
493	func detectAgentByTranscript(ctx context.Context, sessionID string, skip types.AgentName) (agent.Agent, string, error) {
494		for _, name := range agent.List() {
495			if name == skip {
496				continue
497			}
498			ag, err := agent.Get(name)
499			if err != nil {
500				continue
501			}
502			path, resolveErr := resolveAndValidateTranscript(ctx, sessionID, ag)
503			if resolveErr != nil {
504				logging.Debug(ctx, "auto-detect: agent did not match", "agent", string(name), "error", resolveErr)
505				continue
506			}
507			return ag, path, nil
508		}
509		return nil, "", errors.New("transcript not found for any registered agent")
510	}
511	
512	// promptAmendCommit shows the last commit and asks whether to amend it with the checkpoint trailer.
513	// When force is true, it amends without prompting.
514	func promptAmendCommit(ctx context.Context, w io.Writer, headCommit *object.Commit, checkpointIDStr string, force bool) error {
515		shortHash := headCommit.Hash.String()[:7]
516		subject := strings.SplitN(headCommit.Message, "\n", 2)[0]
517	
518		// Skip amending if this exact checkpoint ID is already in the commit.
519		for _, existing := range trailers.ParseAllCheckpoints(headCommit.Message) {
520			if existing.String() == checkpointIDStr {
521				fmt.Fprintf(w, "Commit %s already has Entire-Checkpoint: %s\n", shortHash, checkpointIDStr)
522				return nil
523			}
524		}
525	
526		fmt.Fprintf(w, "\nLast commit: %s %s\n", shortHash, subject)
527	
528		amend := true
529		if !force {
530			if !interactive.CanPromptInteractively() {
531				// Non-interactive: can't prompt, print trailer for manual use.
532				fmt.Fprintf(w, "\nCopy to your commit message to attach:\n\n  Entire-Checkpoint: %s\n", checkpointIDStr)
533				return nil
534			}
535			form := NewAccessibleForm(
536				huh.NewGroup(
537					huh.NewConfirm().
538						Title("Amend the last commit in this branch?").
539						Affirmative("Y").
540						Negative("n").
541						Value(&amend),
542				),
543			)
544			if err := form.Run(); err != nil {
545				return fmt.Errorf("prompt failed: %w", err)
546			}
547		}
548	
549		if !amend {
550			fmt.Fprintf(w, "\nCopy to your commit message to attach:\n\n  Entire-Checkpoint: %s\n", checkpointIDStr)
551			return nil
552		}
553	
554		newMessage := trailers.AppendCheckpointTrailer(headCommit.Message, checkpointIDStr)
555	
556		cmd := exec.CommandContext(ctx, "git", "commit", "--amend", "--only", "-m", newMessage)
557		if output, err := cmd.CombinedOutput(); err != nil {
558			return fmt.Errorf("failed to amend commit: %w\n%s", err, output)
559		}
560	
561		fmt.Fprintf(w, "Amended commit %s with Entire-Checkpoint: %s\n", shortHash, checkpointIDStr)
562		return nil
563	}
564

