1	// lifecycle.go implements the generic lifecycle event dispatcher.
2	// It routes normalized events from any agent to the appropriate framework actions.
3	//
4	// The dispatcher inverts the current flow from "agent handler calls framework functions"
5	// to "framework dispatcher calls agent methods." Agents are passive data providers;
6	// the dispatcher handles all orchestration: state transitions, strategy calls,
7	// file change detection, metadata generation.
8	package cli
9	
10	import (
11		"context"
12		"errors"
13		"fmt"
14		"log/slog"
15		"os"
16		"path/filepath"
17		"strings"
18		"time"
19	
20		"github.com/entireio/cli/cmd/entire/cli/agent"
21		"github.com/entireio/cli/cmd/entire/cli/agent/types"
22		"github.com/entireio/cli/cmd/entire/cli/logging"
23		"github.com/entireio/cli/cmd/entire/cli/paths"
24		"github.com/entireio/cli/cmd/entire/cli/session"
25		"github.com/entireio/cli/cmd/entire/cli/strategy"
26		"github.com/entireio/cli/cmd/entire/cli/transcript"
27		"github.com/entireio/cli/cmd/entire/cli/validation"
28		"github.com/entireio/cli/perf"
29	)
30	
31	// DispatchLifecycleEvent routes a normalized lifecycle event to the appropriate handler.
32	// Returns nil if the event was handled successfully.
33	func DispatchLifecycleEvent(ctx context.Context, ag agent.Agent, event *agent.Event) error {
34		if ag == nil {
35			return errors.New("agent cannot be nil")
36		}
37		if event == nil {
38			return errors.New("event cannot be nil")
39		}
40	
41		switch event.Type {
42		case agent.SessionStart:
43			return handleLifecycleSessionStart(ctx, ag, event)
44		case agent.TurnStart:
45			return handleLifecycleTurnStart(ctx, ag, event)
46		case agent.TurnEnd:
47			return handleLifecycleTurnEnd(ctx, ag, event)
48		case agent.Compaction:
49			return handleLifecycleCompaction(ctx, ag, event)
50		case agent.SessionEnd:
51			return handleLifecycleSessionEnd(ctx, ag, event)
52		case agent.SubagentStart:
53			return handleLifecycleSubagentStart(ctx, ag, event)
54		case agent.SubagentEnd:
55			return handleLifecycleSubagentEnd(ctx, ag, event)
56		case agent.ModelUpdate:
57			return handleLifecycleModelUpdate(ctx, ag, event)
58		default:
59			return fmt.Errorf("unknown lifecycle event type: %d", event.Type)
60		}
61	}
62	
63	// handleLifecycleSessionStart handles session start: shows banner, checks concurrent sessions,
64	// fires state machine transition.
65	func handleLifecycleSessionStart(ctx context.Context, ag agent.Agent, event *agent.Event) error {
66		logCtx := logging.WithAgent(logging.WithComponent(ctx, "lifecycle"), ag.Name())
67		logging.Info(logCtx, "session-start",
68			slog.String("event", event.Type.String()),
69			slog.String("session_id", event.SessionID),
70			slog.String("session_ref", event.SessionRef),
71			slog.String("model", event.Model),
72		)
73	
74		if event.SessionID == "" {
75			return fmt.Errorf("no session_id in %s event", event.Type)
76		}
77		if err := validation.ValidateSessionID(event.SessionID); err != nil {
78			return fmt.Errorf("invalid %s event: %w", event.Type, err)
79		}
80	
81		// Build informational message — warn early if repo has no commits yet,
82		// since checkpoints require at least one commit to work.
83		message := sessionStartMessage(ag.Name(), false)
84		if repo, err := strategy.OpenRepository(ctx); err == nil && strategy.IsEmptyRepository(repo) {
85			message = sessionStartMessage(ag.Name(), true)
86		}
87	
88		// Check for concurrent sessions and append count if any
89		_, countSessionsSpan := perf.Start(ctx, "count_active_sessions")
90		strat := GetStrategy(ctx)
91		if count, err := strat.CountOtherActiveSessionsWithCheckpoints(ctx, event.SessionID); err == nil && count > 0 {
92			if ag.Name() == agent.AgentNameCodex {
93				message += fmt.Sprintf(" %d other active conversation(s) in this workspace will also be included. Use 'entire status' for more information.", count)
94			} else {
95				message += fmt.Sprintf("\n  %d other active conversation(s) in this workspace will also be included.\n  Use 'entire status' for more information.", count)
96			}
97		}
98		countSessionsSpan.End()
99	
100		// Output informational message if the agent supports hook responses.
101		// Claude Code reads JSON from stdout; agents that don't implement
102		// HookResponseWriter silently skip (avoids raw JSON in their terminal).
103		_, hookResponseSpan := perf.Start(ctx, "write_hook_response")
104		if event.ResponseMessage != "" {
105			message = event.ResponseMessage
106		}
107		if writer, ok := agent.AsHookResponseWriter(ag); ok {
108			if err := writer.WriteHookResponse(message); err != nil {
109				hookResponseSpan.RecordError(err)
110				hookResponseSpan.End()
111				return fmt.Errorf("failed to write hook response: %w", err)
112			}
113		}
114		hookResponseSpan.End()
115	
116		// Store model hint if the agent provided model info on SessionStart
117		if event.Model != "" {
118			if err := strategy.StoreModelHint(ctx, event.SessionID, event.Model); err != nil {
119				logging.Warn(logCtx, "failed to store model hint on session start",
120					slog.String("error", err.Error()))
121			}
122		}
123	
124		// Fire EventSessionStart for the current session (if state exists).
125		if state, loadErr := strategy.LoadSessionState(ctx, event.SessionID); loadErr != nil {
126			logging.Warn(logCtx, "failed to load session state on start",
127				slog.String("error", loadErr.Error()))
128		} else if state != nil {
129			persistEventMetadataToState(event, state)
130			if transErr := strategy.TransitionAndLog(ctx, state, session.EventSessionStart, session.TransitionContext{}, session.NoOpActionHandler{}); transErr != nil {
131				logging.Warn(logCtx, "session start transition failed",
132					slog.String("error", transErr.Error()))
133			}
134			if saveErr := strategy.SaveSessionState(ctx, state); saveErr != nil {
135				logging.Warn(logCtx, "failed to update session state on start",
136					slog.String("error", saveErr.Error()))
137			}
138		}
139	
140		return nil
141	}
142	
143	func sessionStartMessage(agentName types.AgentName, emptyRepo bool) string {
144		if agentName == agent.AgentNameCodex {
145			if emptyRepo {
146				return "Entire CLI found no commits yet — checkpoints will activate after your first commit."
147			}
148			return "Entire CLI will link this conversation to your next commit."
149		}
150	
151		if emptyRepo {
152			return "\n\nEntire CLI found no commits yet — checkpoints will activate after your first commit."
153		}
154		return "\n\nEntire CLI will link this conversation to your next commit."
155	}
156	
157	// handleLifecycleModelUpdate persists the model name for the current session.
158	//
159	// If the session state file already exists (e.g., Gemini's BeforeModel fires
160	// after TurnStart), the model is written directly to state.ModelName — no hint
161	// file needed. Otherwise falls back to StoreModelHint for cross-process
162	// persistence (see its doc comment for the full rationale).
163	func handleLifecycleModelUpdate(ctx context.Context, ag agent.Agent, event *agent.Event) error {
164		logCtx := logging.WithAgent(logging.WithComponent(ctx, "lifecycle"), ag.Name())
165		logging.Info(logCtx, "model-update",
166			slog.String("session_id", event.SessionID),
167			slog.String("model", event.Model),
168		)
169	
170		if event.SessionID == "" || event.Model == "" {
171			return nil
172		}
173	
174		// Prefer writing directly to session state when it exists
175		state, loadErr := strategy.LoadSessionState(ctx, event.SessionID)
176		if loadErr != nil {
177			logging.Debug(logCtx, "could not load session state for model update, using hint file",
178				slog.String("error", loadErr.Error()))
179		}
180		if loadErr == nil && state != nil {
181			state.ModelName = event.Model
182			if saveErr := strategy.SaveSessionState(ctx, state); saveErr != nil {
183				logging.Warn(logCtx, "failed to update session state with model",
184					slog.String("error", saveErr.Error()))
185			}
186			return nil
187		}
188	
189		// State doesn't exist yet (or failed to load) — use hint file (see StoreModelHint doc)
190		if err := strategy.StoreModelHint(ctx, event.SessionID, event.Model); err != nil {
191			logging.Warn(logCtx, "failed to store model hint",
192				slog.String("error", err.Error()))
193		}
194	
195		return nil
196	}
197	
198	// handleLifecycleTurnStart handles turn start: captures pre-prompt state,
199	// ensures strategy setup, initializes session.
200	func handleLifecycleTurnStart(ctx context.Context, ag agent.Agent, event *agent.Event) error {
201		logCtx := logging.WithAgent(logging.WithComponent(ctx, "lifecycle"), ag.Name())
202		logging.Info(logCtx, "turn-start",
203			slog.String("event", event.Type.String()),
204			slog.String("session_id", event.SessionID),
205			slog.String("session_ref", event.SessionRef),
206			slog.String("model", event.Model),
207		)
208	
209		sessionID := event.SessionID
210		if sessionID == "" {
211			return fmt.Errorf("no session_id in %s event", event.Type)
212		}
213		if err := validation.ValidateSessionID(sessionID); err != nil {
214			return fmt.Errorf("invalid %s event: %w", event.Type, err)
215		}
216	
217		// Fill model from hint file if the agent didn't provide it on this hook
218		if event.Model == "" {
219			if hint := strategy.LoadModelHint(ctx, sessionID); hint != "" {
220				event.Model = hint
221				logging.Debug(logCtx, "loaded model from hint file",
222					slog.String("model", hint))
223			}
224		}
225	
226		// Capture pre-prompt state (including transcript position via TranscriptAnalyzer)
227		_, captureSpan := perf.Start(ctx, "capture_pre_prompt_state")
228		if err := CapturePrePromptState(ctx, ag, sessionID, event.SessionRef); err != nil {
229			captureSpan.RecordError(err)
230			captureSpan.End()
231			return err
232		}
233		captureSpan.End()
234	
235		// Append prompt to prompt.txt on filesystem so it's available for
236		// mid-turn commits (before SaveStep writes it to the shadow branch).
237		// Prompts are separated by "\n\n---\n\n" to support multiple turns.
238		if event.Prompt != "" {
239			sessionDir := paths.SessionMetadataDirFromSessionID(sessionID)
240			if sessionDirAbs, absErr := paths.AbsPath(ctx, sessionDir); absErr == nil {
241				if mkErr := os.MkdirAll(sessionDirAbs, 0o750); mkErr == nil {
242					promptPath := filepath.Join(sessionDirAbs, paths.PromptFileName)
243					existing, readErr := os.ReadFile(promptPath) //nolint:gosec // session metadata path
244					var content string
245					if readErr == nil && len(existing) > 0 {
246						content = string(existing) + "\n\n---\n\n" + event.Prompt
247					} else {
248						content = event.Prompt
249					}
250					if writeErr := os.WriteFile(promptPath, []byte(content), 0o600); writeErr != nil { //nolint:gosec // path from internal metadata, not user input
251						logging.Warn(logCtx, "failed to write prompt.txt",
252							slog.String("error", writeErr.Error()))
253					}
254				}
255			}
256		}
257	
258		// Ensure strategy setup and initialize session
259		_, initSpan := perf.Start(ctx, "init_session")
260		if err := strategy.EnsureSetup(ctx); err != nil {
261			logging.Warn(logCtx, "failed to ensure strategy setup",
262				slog.String("error", err.Error()))
263		}
264	
265		strat := GetStrategy(ctx)
266		if err := strat.InitializeSession(ctx, sessionID, ag.Type(), event.SessionRef, event.Prompt, event.Model); err != nil {
267			logging.Warn(logCtx, "failed to initialize session state",
268				slog.String("error", err.Error()))
269		}
270	
271		// Best-effort: adopt any pending review marker written by `entire review`
272		// before spawning the agent. Errors in load/save must not fail the turn.
273		if stateStore, storeErr := session.NewStateStore(ctx); storeErr != nil {
274			logging.Warn(logCtx, "failed to create state store for review marker adoption",
275				slog.String("error", storeErr.Error()))
276		} else if state, loadErr := stateStore.Load(ctx, sessionID); loadErr != nil {
277			logging.Warn(logCtx, "failed to load session state for review marker adoption",
278				slog.String("error", loadErr.Error()))
279		} else if state != nil {
280			if updated, modified, adoptErr := adoptPendingReviewMarkerInto(logCtx, *state, ag.Name()); adoptErr != nil {
281				logging.Warn(logCtx, "failed to adopt pending review marker",
282					slog.String("error", adoptErr.Error()))
283			} else if modified {
284				if saveErr := stateStore.Save(ctx, &updated); saveErr != nil {
285					logging.Warn(logCtx, "failed to save session state after review marker adoption",
286						slog.String("error", saveErr.Error()))
287				}
288			}
289		}
290		initSpan.End()
291	
292		return nil
293	}
294	
295	// handleLifecycleTurnEnd handles turn end: validates transcript, extracts metadata,
296	// detects file changes, saves step + checkpoint, transitions phase.
297	//
298	//nolint:maintidx // high complexity due to sequential orchestration of 8 steps (validation, extraction, file detection, filtering, token calc, step save, phase transition, cleanup) - splitting would obscure the flow
299	func handleLifecycleTurnEnd(ctx context.Context, ag agent.Agent, event *agent.Event) error {
300		logCtx := logging.WithAgent(logging.WithComponent(ctx, "lifecycle"), ag.Name())
301		logging.Info(logCtx, "turn-end",
302			slog.String("event", event.Type.String()),
303			slog.String("session_id", event.SessionID),
304			slog.String("session_ref", event.SessionRef),
305			slog.String("model", event.Model),
306		)
307	
308		sessionID := event.SessionID
309		if sessionID == "" {
310			sessionID = unknownSessionID
311		}
312	
313		// Fill model from hint file if the agent didn't provide it on this hook
314		if event.Model == "" && sessionID != unknownSessionID {
315			if hint := strategy.LoadModelHint(ctx, sessionID); hint != "" {
316				event.Model = hint
317				logging.Debug(logCtx, "loaded model from hint file",
318					slog.String("model", hint))
319			}
320		}
321	
322		transcriptRef := event.SessionRef
323		if transcriptRef == "" {
324			return errors.New("transcript file not specified")
325		}
326	
327		// If agent implements TranscriptPreparer, materialize the transcript file.
328		// This must run BEFORE fileExists: agents like OpenCode lazily fetch transcripts
329		// via `opencode export`, so the file doesn't exist until PrepareTranscript creates it.
330		// Claude Code's PrepareTranscript just flushes (always succeeds). Agents without
331		// TranscriptPreparer (Gemini, Droid) are unaffected.
332		_, prepareSpan := perf.Start(ctx, "prepare_and_validate_transcript")
333		if preparer, ok := agent.AsTranscriptPreparer(ag); ok {
334			if err := preparer.PrepareTranscript(ctx, transcriptRef); err != nil {
335				logging.Warn(logCtx, "failed to prepare transcript",
336					slog.String("error", err.Error()))
337			}
338		}
339	
340		if !fileExists(transcriptRef) {
341			prepareSpan.RecordError(fmt.Errorf("transcript file not found: %s", transcriptRef))
342			prepareSpan.End()
343			return fmt.Errorf("transcript file not found: %s", transcriptRef)
344		}
345	
346		// Early check: bail out quickly if the repo has no commits yet.
347		// Return nil (not an error) so the hook exits 0 — agents treat non-zero
348		// exit codes as hook failures. The user was already warned at session start.
349		if repo, err := strategy.OpenRepository(ctx); err == nil && strategy.IsEmptyRepository(repo) {
350			prepareSpan.End()
351			logging.Info(logCtx, "skipping checkpoint - will activate after first commit")
352			return nil
353		}
354		prepareSpan.End()
355	
356		// Create session metadata directory
357		_, copySpan := perf.Start(ctx, "copy_transcript")
358		sessionDir := paths.SessionMetadataDirFromSessionID(sessionID)
359		sessionDirAbs, err := paths.AbsPath(ctx, sessionDir)
360		if err != nil {
361			sessionDirAbs = sessionDir
362		}
363		if err := os.MkdirAll(sessionDirAbs, 0o750); err != nil {
364			copySpan.RecordError(err)
365			copySpan.End()
366			return fmt.Errorf("failed to create session directory: %w", err)
367		}
368	
369		// Copy transcript to session directory
370		transcriptData, err := ag.ReadTranscript(transcriptRef)
371		if err != nil {
372			copySpan.RecordError(err)
373			copySpan.End()
374			return fmt.Errorf("failed to read transcript: %w", err)
375		}
376		logFile := filepath.Join(sessionDirAbs, paths.TranscriptFileName)
377		if err := os.WriteFile(logFile, transcriptData, 0o600); err != nil {
378			copySpan.RecordError(err)
379			copySpan.End()
380			return fmt.Errorf("failed to write transcript: %w", err)
381		}
382		logging.Debug(logCtx, "copied transcript",
383			slog.String("path", sessionDir+"/"+paths.TranscriptFileName))
384		copySpan.End()
385	
386		// Load pre-prompt state (captured on TurnStart)
387		_, extractSpan := perf.Start(ctx, "extract_metadata")
388		preState, err := LoadPrePromptState(ctx, sessionID)
389		if err != nil {
390			logging.Warn(logCtx, "failed to load pre-prompt state",
391				slog.String("error", err.Error()))
392		}
393	
394		// Determine transcript offset
395		transcriptOffset := resolveTranscriptOffset(ctx, preState, sessionID)
396	
397		// Backfill prompt.txt from transcript when prompt data is missing.
398		// This handles agents whose exec mode doesn't fire UserPromptSubmit (e.g., Factory AI
399		// Droid). The transcript is the source of truth — if ExtractPrompts returns nothing,
400		// there genuinely were no prompts. We track whether backfill occurred so we can
401		// update session state after SaveStep (which may reinitialize state).
402		var backfilledPrompt string
403		promptPath := filepath.Join(sessionDirAbs, paths.PromptFileName)
404		existingPrompt, readPromptErr := os.ReadFile(promptPath) //nolint:gosec // file content is safe session metadata
405		if readPromptErr != nil && !os.IsNotExist(readPromptErr) {
406			logging.Warn(logCtx, "failed to read prompt.txt, skipping backfill",
407				slog.String("error", readPromptErr.Error()))
408		} else if len(existingPrompt) == 0 {
409			if extractor, ok := agent.AsPromptExtractor(ag); ok {
410				prompts, extractErr := extractor.ExtractPrompts(transcriptRef, transcriptOffset)
411				if extractErr != nil {
412					logging.Warn(logCtx, "failed to extract prompts from transcript",
413						slog.String("error", extractErr.Error()))
414				} else if len(prompts) > 0 {
415					content := strings.Join(prompts, "\n\n---\n\n")
416					if writeErr := os.WriteFile(promptPath, []byte(content), 0o600); writeErr != nil {
417						logging.Warn(logCtx, "failed to backfill prompt.txt from transcript",
418							slog.String("error", writeErr.Error()))
419					} else {
420						logging.Debug(logCtx, "backfilled prompt.txt from transcript",
421							slog.Int("prompt_count", len(prompts)))
422						backfilledPrompt = prompts[len(prompts)-1]
423					}
424				}
425			}
426		}
427	
428		// Compute subagents directory for agents that support subagent extraction.
429		// Subagent transcripts live in <transcriptDir>/<modelSessionID>/subagents/
430		subagentsDir := filepath.Join(filepath.Dir(transcriptRef), event.SessionID, "subagents")
431	
432		// Extract metadata via agent interface (modified files)
433		var modifiedFiles []string
434	
435		if analyzer, ok := agent.AsTranscriptAnalyzer(ag); ok {
436			// Extract modified files - prefer SubagentAwareExtractor if available to include subagent files
437			if subagentExtractor, subOk := agent.AsSubagentAwareExtractor(ag); subOk {
438				if files, fileErr := subagentExtractor.ExtractAllModifiedFiles(transcriptData, transcriptOffset, subagentsDir); fileErr != nil {
439					logging.Warn(logCtx, "failed to extract modified files (with subagents)",
440						slog.String("error", fileErr.Error()))
441				} else {
442					modifiedFiles = files
443				}
444			} else {
445				// Fall back to basic extraction (main transcript only)
446				if files, _, fileErr := analyzer.ExtractModifiedFilesFromOffset(transcriptRef, transcriptOffset); fileErr != nil {
447					logging.Warn(logCtx, "failed to extract modified files",
448						slog.String("error", fileErr.Error()))
449				} else {
450					modifiedFiles = files
451				}
452			}
453		}
454		extractSpan.End()
455	
456		// Generate commit message from last prompt (read from session state, set at TurnStart).
457		// In exec mode, session state LastPrompt may be empty because UserPromptSubmit never fires.
458		// Fall back to backfilledPrompt extracted from the transcript.
459		// Single load serves both prompt retrieval and backfill.
460		_, commitMsgSpan := perf.Start(ctx, "generate_commit_message")
461		lastPrompt := ""
462		if sessionState, stateErr := strategy.LoadSessionState(ctx, sessionID); stateErr == nil && sessionState != nil {
463			lastPrompt = sessionState.LastPrompt
464			// Backfill LastPrompt so `entire status` shows the prompt even when
465			// no files were modified (before the early return below).
466			if lastPrompt == "" && backfilledPrompt != "" {
467				lastPrompt = backfilledPrompt
468				sessionState.LastPrompt = backfilledPrompt
469				if saveErr := strategy.SaveSessionState(ctx, sessionState); saveErr != nil {
470					logging.Warn(logCtx, "failed to backfill LastPrompt in session state",
471						slog.String("error", saveErr.Error()))
472				}
473			}
474		} else if backfilledPrompt != "" {
475			lastPrompt = backfilledPrompt
476		}
477		commitMessage := generateCommitMessage(lastPrompt, ag.Type())
478		logging.Debug(logCtx, "using commit message",
479			slog.Int("message_length", len(commitMessage)))
480		commitMsgSpan.End()
481	
482		// Get worktree root for path normalization
483		_, detectSpan := perf.Start(ctx, "detect_file_changes")
484		repoRoot, err := paths.WorktreeRoot(ctx)
485		if err != nil {
486			detectSpan.RecordError(err)
487			detectSpan.End()
488			return fmt.Errorf("failed to get worktree root: %w", err)
489		}
490	
491		var preUntrackedFiles []string
492		if preState != nil {
493			logging.Debug(logCtx, "pre-prompt state",
494				slog.Int("pre_existing_untracked_files", len(preState.UntrackedFiles)))
495			preUntrackedFiles = preState.PreUntrackedFiles()
496		}
497	
498		// Detect file changes via git status
499		changes, err := DetectFileChanges(ctx, preUntrackedFiles)
500		if err != nil {
501			logging.Warn(logCtx, "failed to compute file changes",
502				slog.String("error", err.Error()))
503		}
504		detectSpan.End()
505	
506		// Filter and normalize all paths
507		_, normalizeSpan := perf.Start(ctx, "filter_and_normalize_paths")
508		relModifiedFiles := FilterAndNormalizePaths(modifiedFiles, repoRoot)
509		var relNewFiles, relDeletedFiles []string
510		if changes != nil {
511			relNewFiles = FilterAndNormalizePaths(changes.New, repoRoot)
512			relDeletedFiles = FilterAndNormalizePaths(changes.Deleted, repoRoot)
513	
514			// Merge git-status modified files as a fallback for transcript parsing.
515			// Transcript parsing is the primary source for modified files, but it can miss
516			// files if the agent uses an unrecognized tool or the transcript format changes.
517			// Git status catches any tracked file with working-tree changes.
518			relModifiedFiles = mergeUnique(relModifiedFiles, FilterAndNormalizePaths(changes.Modified, repoRoot))
519		}
520	
521		// Filter transcript-extracted files to exclude files already committed to HEAD.
522		// When an agent commits files mid-turn, those files are condensed by PostCommit
523		// and should not be re-added to FilesTouched by SaveStep. A file is "committed"
524		// if it exists in HEAD with the same content as the working tree.
525		relModifiedFiles = filterToUncommittedFiles(ctx, relModifiedFiles, repoRoot)
526		normalizeSpan.End()
527	
528		// Check if there are any changes
529		totalChanges := len(relModifiedFiles) + len(relNewFiles) + len(relDeletedFiles)
530		if totalChanges == 0 {
531			logging.Info(logCtx, "no files modified during session, skipping checkpoint")
532			transitionSessionTurnEnd(ctx, sessionID, event)
533			if cleanupErr := CleanupPrePromptState(ctx, sessionID); cleanupErr != nil {
534				logging.Warn(logCtx, "failed to cleanup pre-prompt state",
535					slog.String("error", cleanupErr.Error()))
536			}
537			return nil
538		}
539	
540		// Log file changes
541		logFileChanges(ctx, relModifiedFiles, relNewFiles, relDeletedFiles)
542	
543		// Get git author
544		author, err := GetGitAuthor(ctx)
545		if err != nil {
546			return fmt.Errorf("failed to get git author: %w", err)
547		}
548	
549		// Get strategy and agent type
550		strat := GetStrategy(ctx)
551		agentType := ag.Type()
552	
553		// Get transcript position/identifier from pre-prompt state
554		var transcriptIdentifierAtStart string
555		var transcriptLinesAtStart int
556		if preState != nil {
557			transcriptIdentifierAtStart = preState.LastTranscriptIdentifier
558			transcriptLinesAtStart = preState.TranscriptOffset
559		}
560	
561		// Calculate token usage - prefer SubagentAwareExtractor to include subagent tokens
562		tokenUsage := agent.CalculateTokenUsage(ctx, ag, transcriptData, transcriptLinesAtStart, subagentsDir)
563	
564		// Build fully-populated step context and delegate to strategy
565		stepCtx := strategy.StepContext{
566			SessionID:                sessionID,
567			ModifiedFiles:            relModifiedFiles,
568			NewFiles:                 relNewFiles,
569			DeletedFiles:             relDeletedFiles,
570			MetadataDir:              sessionDir,
571			MetadataDirAbs:           sessionDirAbs,
572			CommitMessage:            commitMessage,
573			TranscriptPath:           transcriptRef,
574			AuthorName:               author.Name,
575			AuthorEmail:              author.Email,
576			AgentType:                agentType,
577			StepTranscriptIdentifier: transcriptIdentifierAtStart,
578			StepTranscriptStart:      transcriptLinesAtStart,
579			TokenUsage:               tokenUsage,
580		}
581	
582		if err := strat.SaveStep(ctx, stepCtx); err != nil {
583			return fmt.Errorf("failed to save step: %w", err)
584		}
585	
586		// Update session state with backfilled prompt after SaveStep.
587		// Done after SaveStep because SaveStep may reinitialize session state,
588		// which would overwrite an earlier LastPrompt update.
589		if backfilledPrompt != "" {
590			if state, stateErr := strategy.LoadSessionState(ctx, sessionID); stateErr == nil && state != nil && state.LastPrompt == "" {
591				state.LastPrompt = backfilledPrompt
592				if saveErr := strategy.SaveSessionState(ctx, state); saveErr != nil {
593					logging.Warn(logCtx, "failed to backfill LastPrompt in session state",
594						slog.String("error", saveErr.Error()))
595				}
596			}
597		}
598	
599		// Transition session phase and cleanup
600		transitionSessionTurnEnd(ctx, sessionID, event)
601		if cleanupErr := CleanupPrePromptState(ctx, sessionID); cleanupErr != nil {
602			logging.Warn(logCtx, "failed to cleanup pre-prompt state",
603				slog.String("error", cleanupErr.Error()))
604		}
605	
606		return nil
607	}
608	
609	// handleLifecycleCompaction handles context compaction: saves current progress
610	// but stays in ACTIVE phase (unlike TurnEnd which transitions to IDLE).
611	// Also resets the transcript offset since the transcript may be truncated.
612	func handleLifecycleCompaction(ctx context.Context, ag agent.Agent, event *agent.Event) error {
613		logCtx := logging.WithAgent(logging.WithComponent(ctx, "lifecycle"), ag.Name())
614		logging.Info(logCtx, "compaction",
615			slog.String("event", event.Type.String()),
616			slog.String("session_id", event.SessionID),
617		)
618	
619		// Fire EventCompaction to trigger ActionCondenseIfFilesTouched (stays in ACTIVE)
620		sessionID := event.SessionID
621		sessionState, loadErr := strategy.LoadSessionState(ctx, sessionID)
622		if loadErr != nil {
623			logging.Warn(logCtx, "failed to load session state for compaction",
624				slog.String("error", loadErr.Error()))
625		}
626		if sessionState != nil {
627			persistEventMetadataToState(event, sessionState)
628	
629			if transErr := strategy.TransitionAndLog(ctx, sessionState, session.EventCompaction, session.TransitionContext{}, session.NoOpActionHandler{}); transErr != nil {
630				logging.Warn(logCtx, "compaction transition failed",
631					slog.String("error", transErr.Error()))
632			}
633	
634			if saveErr := strategy.SaveSessionState(ctx, sessionState); saveErr != nil {
635				logging.Warn(logCtx, "failed to save session state after compaction",
636					slog.String("error", saveErr.Error()))
637			}
638		}
639	
640		logging.Info(logCtx, "context compaction detected")
641		return nil
642	}
643	
644	// handleLifecycleSessionEnd handles session end: marks the session as ended.
645	func handleLifecycleSessionEnd(ctx context.Context, ag agent.Agent, event *agent.Event) error {
646		logCtx := logging.WithAgent(logging.WithComponent(ctx, "lifecycle"), ag.Name())
647		logging.Info(logCtx, "session-end",
648			slog.String("event", event.Type.String()),
649			slog.String("session_id", event.SessionID),
650		)
651	
652		if event.SessionID == "" {
653			return nil // No session to update
654		}
655	
656		// Note: We intentionally don't clean up cached transcripts here.
657		// Post-session commits (carry-forward in ENDED phase) may still need
658		// the transcript to extract file changes. Cleanup is handled by
659		// `entire clean` or when the session state is fully removed.
660	
661		if err := markSessionEnded(ctx, event, event.SessionID); err != nil {
662			logging.Warn(logCtx, "failed to mark session ended",
663				slog.String("error", err.Error()))
664			// Don't attempt eager condense if we couldn't even mark the session ended —
665			// the session state may be in an inconsistent state.
666			return nil
667		}
668	
669		// Eagerly condense session data so PostCommit doesn't have to process it.
670		// This prevents zombie ENDED sessions from accumulating and causing O(N)
671		// overhead on every future commit (GitHub issue #591).
672		// Fail-open: if this fails, PostCommit will still process it on the next commit.
673		strat := GetStrategy(ctx)
674		if err := strat.CondenseAndMarkFullyCondensed(ctx, event.SessionID); err != nil {
675			logging.Warn(logCtx, "eager condense on session stop failed",
676				slog.String("session_id", event.SessionID),
677				slog.String("error", err.Error()))
678		}
679	
680		return nil
681	}
682	
683	// handleLifecycleSubagentStart handles subagent start: captures pre-task state.
684	func handleLifecycleSubagentStart(ctx context.Context, ag agent.Agent, event *agent.Event) error {
685		logCtx := logging.WithAgent(logging.WithComponent(ctx, "lifecycle"), ag.Name())
686		logging.Info(logCtx, "subagent started",
687			slog.String("event", event.Type.String()),
688			slog.String("session_id", event.SessionID),
689			slog.String("tool_use_id", event.ToolUseID),
690			slog.String("transcript", event.SessionRef),
691		)
692	
693		// Capture pre-task state
694		if err := CapturePreTaskState(ctx, event.ToolUseID); err != nil {
695			return fmt.Errorf("failed to capture pre-task state: %w", err)
696		}
697	
698		return nil
699	}
700	
701	// handleLifecycleSubagentEnd handles subagent end: detects changes, saves task checkpoint.
702	func handleLifecycleSubagentEnd(ctx context.Context, ag agent.Agent, event *agent.Event) error {
703		logCtx := logging.WithAgent(logging.WithComponent(ctx, "lifecycle"), ag.Name())
704		if event.SubagentType == "" && event.TaskDescription == "" {
705			// Extract subagent type and description from tool input
706			event.SubagentType, event.TaskDescription = ParseSubagentTypeAndDescription(event.ToolInput)
707		}
708	
709		// Determine subagent transcript path
710		transcriptDir := filepath.Dir(event.SessionRef)
711		var subagentTranscriptPath string
712		if event.SubagentID != "" {
713			subagentTranscriptPath = AgentTranscriptPath(transcriptDir, event.SubagentID)
714			if !fileExists(subagentTranscriptPath) {
715				subagentTranscriptPath = ""
716			}
717		}
718	
719		// Log context
720		subagentEndAttrs := []any{
721			slog.String("event", event.Type.String()),
722			slog.String("session_id", event.SessionID),
723			slog.String("tool_use_id", event.ToolUseID),
724		}
725		if event.SubagentID != "" {
726			subagentEndAttrs = append(subagentEndAttrs, slog.String("agent_id", event.SubagentID))
727		}
728		if subagentTranscriptPath != "" {
729			subagentEndAttrs = append(subagentEndAttrs, slog.String("subagent_transcript", subagentTranscriptPath))
730		}
731		logging.Info(logCtx, "subagent completed", subagentEndAttrs...)
732	
733		// Extract modified files from hook payload and/or subagent transcript
734		var modifiedFiles []string
735		modifiedFiles = append(modifiedFiles, event.ModifiedFiles...)
736		if analyzer, ok := agent.AsTranscriptAnalyzer(ag); ok {
737			transcriptToScan := event.SessionRef
738			if subagentTranscriptPath != "" {
739				transcriptToScan = subagentTranscriptPath
740			}
741			if files, _, fileErr := analyzer.ExtractModifiedFilesFromOffset(transcriptToScan, 0); fileErr != nil {
742				logging.Warn(logCtx, "failed to extract modified files from subagent",
743					slog.String("error", fileErr.Error()))
744			} else {
745				modifiedFiles = mergeUnique(modifiedFiles, files)
746			}
747		}
748	
749		// Load pre-task state and detect file changes.
750		// If no pre-task state exists (agent doesn't support pre-task hook), fall back
751		// to the session's pre-prompt state. Without either, DetectFileChanges receives
752		// nil and treats ALL untracked files as new — which would create spurious task
753		// checkpoints for pre-existing untracked files (e.g., .github/hooks/entire.json).
754		preState, err := LoadPreTaskState(ctx, event.ToolUseID)
755		if err != nil {
756			logging.Warn(logCtx, "failed to load pre-task state",
757				slog.String("error", err.Error()))
758		}
759		var preUntrackedFiles []string
760		if preState != nil {
761			preUntrackedFiles = preState.PreUntrackedFiles()
762		}
763		changes, err := DetectFileChanges(ctx, preUntrackedFiles)
764		if err != nil {
765			logging.Warn(logCtx, "failed to compute file changes",
766				slog.String("error", err.Error()))
767		}
768	
769		// Get worktree root and normalize paths
770		repoRoot, err := paths.WorktreeRoot(ctx)
771		if err != nil {
772			return fmt.Errorf("failed to get worktree root: %w", err)
773		}
774	
775		relModifiedFiles := FilterAndNormalizePaths(modifiedFiles, repoRoot)
776		var relNewFiles, relDeletedFiles []string
777		if changes != nil {
778			relNewFiles = FilterAndNormalizePaths(changes.New, repoRoot)
779			relDeletedFiles = FilterAndNormalizePaths(changes.Deleted, repoRoot)
780			relModifiedFiles = mergeUnique(relModifiedFiles, FilterAndNormalizePaths(changes.Modified, repoRoot))
781		}
782	
783		// If no changes, skip
784		if len(relModifiedFiles) == 0 && len(relNewFiles) == 0 && len(relDeletedFiles) == 0 {
785			logging.Info(logCtx, "no file changes detected, skipping task checkpoint")
786			_ = CleanupPreTaskState(ctx, event.ToolUseID) //nolint:errcheck // best-effort cleanup
787			return nil
788		}
789	
790		// Find checkpoint UUID from main transcript (best-effort)
791		var checkpointUUID string
792		// Use the existing CLI-level checkpoint UUID finder
793		mainLines, _ := parseTranscriptForCheckpointUUID(event.SessionRef) //nolint:errcheck // best-effort
794		if mainLines != nil {
795			checkpointUUID, _ = FindCheckpointUUID(mainLines, event.ToolUseID)
796		}
797	
798		// Get git author
799		author, err := GetGitAuthor(ctx)
800		if err != nil {
801			return fmt.Errorf("failed to get git author: %w", err)
802		}
803	
804		// Build task checkpoint context
805		strat := GetStrategy(ctx)
806		agentType := ag.Type()
807	
808		taskStepCtx := strategy.TaskStepContext{
809			SessionID:              event.SessionID,
810			ToolUseID:              event.ToolUseID,
811			AgentID:                event.SubagentID,
812			ModifiedFiles:          relModifiedFiles,
813			NewFiles:               relNewFiles,
814			DeletedFiles:           relDeletedFiles,
815			TranscriptPath:         event.SessionRef,
816			SubagentTranscriptPath: subagentTranscriptPath,
817			CheckpointUUID:         checkpointUUID,
818			AuthorName:             author.Name,
819			AuthorEmail:            author.Email,
820			SubagentType:           event.SubagentType,
821			TaskDescription:        event.TaskDescription,
822			AgentType:              agentType,
823		}
824	
825		if err := strat.SaveTaskStep(ctx, taskStepCtx); err != nil {
826			return fmt.Errorf("failed to save task step: %w", err)
827		}
828	
829		_ = CleanupPreTaskState(ctx, event.ToolUseID) //nolint:errcheck // best-effort cleanup
830		return nil
831	}
832	
833	// --- Helper functions ---
834	
835	// resolveTranscriptOffset determines the transcript offset to use for parsing.
836	// Prefers pre-prompt state, falls back to session state.
837	func resolveTranscriptOffset(ctx context.Context, preState *PrePromptState, sessionID string) int {
838		logCtx := logging.WithComponent(ctx, "lifecycle")
839		if preState != nil && preState.TranscriptOffset > 0 {
840			logging.Debug(logCtx, "pre-prompt state found, parsing transcript from offset",
841				slog.Int("offset", preState.TranscriptOffset))
842			return preState.TranscriptOffset
843		}
844	
845		// Fall back to session state
846		sessionState, loadErr := strategy.LoadSessionState(ctx, sessionID)
847		if loadErr != nil {
848			logging.Warn(logCtx, "failed to load session state",
849				slog.String("error", loadErr.Error()))
850			return 0
851		}
852		if sessionState != nil && sessionState.CheckpointTranscriptStart > 0 {
853			logging.Debug(logCtx, "session state found, parsing transcript from offset",
854				slog.Int("offset", sessionState.CheckpointTranscriptStart))
855			return sessionState.CheckpointTranscriptStart
856		}
857	
858		return 0
859	}
860	
861	// parseTranscriptForCheckpointUUID is a thin wrapper around transcript parsing for checkpoint UUID lookup.
862	// Returns parsed transcript lines for use with FindCheckpointUUID.
863	func parseTranscriptForCheckpointUUID(transcriptPath string) ([]transcriptLine, error) {
864		lines, err := transcript.ParseFromFileAtLine(transcriptPath, 0)
865		if err != nil {
866			return nil, fmt.Errorf("parsing transcript for checkpoint UUID: %w", err)
867		}
868		return lines, nil
869	}
870	
871	// transitionSessionTurnEnd transitions the session phase to IDLE and dispatches turn-end actions.
872	func transitionSessionTurnEnd(ctx context.Context, sessionID string, event *agent.Event) {
873		logCtx := logging.WithComponent(ctx, "lifecycle")
874		turnState, loadErr := strategy.LoadSessionState(ctx, sessionID)
875		if loadErr != nil {
876			logging.Warn(logCtx, "failed to load session state for turn end",
877				slog.String("error", loadErr.Error()))
878			return
879		}
880		if turnState == nil {
881			return
882		}
883	
884		persistEventMetadataToState(event, turnState)
885	
886		if err := strategy.TransitionAndLog(ctx, turnState, session.EventTurnEnd, session.TransitionContext{}, session.NoOpActionHandler{}); err != nil {
887			logging.Warn(logCtx, "turn-end transition failed",
888				slog.String("error", err.Error()))
889		}
890	
891		// Always dispatch to strategy for turn-end handling. The strategy reads
892		// work items from state (e.g. TurnCheckpointIDs), not the action list.
893		strat := GetStrategy(ctx)
894		if err := strat.HandleTurnEnd(ctx, turnState); err != nil {
895			logging.Warn(logCtx, "turn-end action dispatch failed",
896				slog.String("error", err.Error()))
897		}
898	
899		if updateErr := strategy.SaveSessionState(ctx, turnState); updateErr != nil {
900			logging.Warn(logCtx, "failed to update session phase on turn end",
901				slog.String("error", updateErr.Error()))
902		}
903	}
904	
905	// markSessionEnded transitions the session to ENDED phase via the state machine.
906	// If event is non-nil, hook-provided metrics are persisted to state before saving.
907	func markSessionEnded(ctx context.Context, event *agent.Event, sessionID string) error {
908		state, err := strategy.LoadSessionState(ctx, sessionID)
909		if err != nil {
910			return fmt.Errorf("failed to load session state: %w", err)
911		}
912		if state == nil {
913			return nil // No state file, nothing to update
914		}
915	
916		if event != nil {
917			persistEventMetadataToState(event, state)
918		}
919	
920		if transErr := strategy.TransitionAndLog(ctx, state, session.EventSessionStop, session.TransitionContext{}, session.NoOpActionHandler{}); transErr != nil {
921			logging.Warn(logging.WithComponent(ctx, "lifecycle"), "session stop transition failed",
922				slog.String("error", transErr.Error()))
923		}
924	
925		now := time.Now()
926		state.EndedAt = &now
927	
928		if err := strategy.SaveSessionState(ctx, state); err != nil {
929			return fmt.Errorf("failed to save session state: %w", err)
930		}
931		return nil
932	}
933	
934	// logFileChanges logs the files modified, created, and deleted during a session.
935	func logFileChanges(ctx context.Context, modified, newFiles, deleted []string) {
936		logCtx := logging.WithComponent(ctx, "lifecycle")
937		logging.Debug(logCtx, "files changed during session",
938			slog.Int("modified", len(modified)),
939			slog.Int("new", len(newFiles)),
940			slog.Int("deleted", len(deleted)))
941	}
942	
943	func persistEventMetadataToState(event *agent.Event, state *strategy.SessionState) {
944		// Update ModelName if provided (model is known by turn-end even on first turn)
945		if event.Model != "" {
946			state.ModelName = event.Model
947		}
948	
949		// Persist hook-provided session metrics (e.g., from Cursor hooks)
950		if event.DurationMs > 0 {
951			state.SessionDurationMs = event.DurationMs
952		}
953		// Use hook-reported turn count if available (take max); otherwise
954		// increment on each TurnEnd event to count turns ourselves.
955		if event.TurnCount > 0 {
956			if event.TurnCount > state.SessionTurnCount {
957				state.SessionTurnCount = event.TurnCount
958			}
959		} else if event.Type == agent.TurnEnd {
960			state.SessionTurnCount++
961		}
962		if event.ContextTokens > 0 {
963			state.ContextTokens = event.ContextTokens
964		}
965		if event.ContextWindowSize > 0 {
966			state.ContextWindowSize = event.ContextWindowSize
967		}
968	}
