1130	// Reproduces the stale-marker problem: `entire review` for a non-
1131	// launchable agent writes a marker at SHA A, then the user commits
1132	// (HEAD moves to SHA B) before starting the review session. The later
1133	// session must NOT adopt the now-stale marker — that would tag an
1134	// unrelated session as a review of code that has already moved on.
1135	// The stale marker is discarded so future sessions start clean.
1136	func TestAdoptPendingReviewMarker_StaleSHAClearsMarker(t *testing.T) {
1137		tmp := t.TempDir()
1138		testutil.InitRepo(t, tmp)
1139		testutil.WriteFile(t, tmp, "f.txt", "x")
1140		testutil.GitAdd(t, tmp, "f.txt")
1141		testutil.GitCommit(t, tmp, "init")
1142		t.Chdir(tmp)
1143	
1144		// Marker written at a SHA that isn't current HEAD (simulating HEAD
1145		// having moved since `entire review` was invoked for a non-launchable
1146		// agent and the user then committed before starting the session).
1147		const staleSHA = "0000000000000000000000000000000000000000"
1148		if err := WritePendingReviewMarker(context.Background(), PendingReviewMarker{
1149			AgentName:    string(agent.AgentNameClaudeCode),
1150			Skills:       []string{"/pr-review-toolkit:review-pr"},
1151			StartingSHA:  staleSHA,
1152			StartedAt:    time.Now().UTC(),
1153			WorktreePath: tmp,
1154		}); err != nil {
1155			t.Fatal(err)
1156		}
1157	
1158		// Matching agent + worktree, but SHA has drifted — discard the marker.
1159		got, modified, err := adoptPendingReviewMarkerInto(context.Background(), session.State{
1160			SessionID:    "later-session",
1161			WorktreePath: tmp,
1162		}, agent.AgentNameClaudeCode)
1163		if err != nil {
1164			t.Fatal(err)
1165		}
1166		if modified {
1167			t.Fatal("expected modified=false when marker SHA != current HEAD SHA")
1168		}
1169		if got.Kind != "" {
1170			t.Errorf("Kind = %q, want empty (stale marker must not tag session)", got.Kind)
1171		}
1172	
1173		// Marker must be CLEARED (not left in place) — no future session will
1174		// legitimately match the stale SHA, so leaving it would let it mis-tag
1175		// subsequent unrelated sessions.
1176		_, markerPresent, readErr := ReadPendingReviewMarker(context.Background())
1177		if readErr != nil {
1178			t.Fatal(readErr)
1179		}
1180		if markerPresent {
1181			t.Error("expected stale marker to be cleared, not preserved")
1182		}
1183	}
