1186	// claude-code, but a cursor session fires its UserPromptSubmit hook first in
1187	// the same worktree. The wrong-agent session must NOT claim the marker —
1188	// whichever agent's hook happens to fire first would otherwise silently
1189	// steal a review meant for a different agent (with different skills).
1190	func TestAdoptPendingReviewMarker_DifferentAgentLeavesMarker(t *testing.T) {
